293→// CheckpointIDs lists all checkpoint IDs from the tree at the tip of the
294→// checkpoint branch. It parses the two-level directory structure
295→// ({prefix}/{suffix}/metadata.json) and returns the concatenated IDs.
296→func CheckpointIDs(t *testing.T, dir string) []string {
297→	t.Helper()
298→	out := gitOutputSafe(dir, "ls-tree", "-r", "--name-only", "entire/checkpoints/v1")
299→	if out == "" {
300→		return nil
301→	}
302→	seen := map[string]bool{}
303→	var ids []string
304→	for _, line := range strings.Split(strings.TrimSpace(out), "\n") {
305→		// Match {prefix}/{suffix}/metadata.json (top-level, not session-level)
306→		parts := strings.Split(line, "/")
307→		if len(parts) == 3 && parts[2] == "metadata.json" {
308→			id := parts[0] + parts[1]
309→			if !seen[id] {
310→				seen[id] = true
311→				ids = append(ids, id)
312→			}
313→		}
314→	}
315→	return ids
316→}
